def max_path_sum(triangle, row, col):
    if row == 0:
        return triangle[0][col]

    # Check if current position is valid
    if col < 0 or col >= len(triangle[row]):
        return float('-inf')

    # Recursive case: get max from left and right children
    left = max_path_sum(triangle, row - 1, col)
    right = max_path_sum(triangle, row - 1, col + 1)

    return triangle[row][col] + max(left, right)

